## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/lowGradeGliomaLogic.ts`

```typescript
/**
 * Diffuse Low-Grade Glioma Clinical Logic Engine
 *
 * Based on:
 * - SEOM-GEINO Clinical Guidelines for Grade 2 Gliomas (2024, Clin Transl Oncol)
 * - WHO Classification of Tumors of the CNS 2021 (Louis DN et al., Acta Neuropathol 2021)
 * - EORTC 22033-26033 Trial (Baumert BG et al., Lancet Oncol 2016)
 * - RTOG 9802 Trial (Buckner JC et al., N Engl J Med 2016)
 * - INDIGO Trial — Vorasidenib (Mellinghoff IK et al., N Engl J Med 2023)
 * - CNS 2025 Diffuse Low-Grade Glioma Guidelines
 *
 * PMIDs: 38662171, 34185076, 26598715, 37610921
 */

// ─── Types ────────────────────────────────────────────────────────────────────

export type IDHStatus =
  | "idh_mutant_1p19q_codeleted" // Oligodendroglioma WHO Grade 2/3
  | "idh_mutant_atrx_mutant" // Astrocytoma WHO Grade 2/3
  | "idh_wildtype" // Likely GBM — reclassify
  | "unknown"; // Pending molecular testing

export type RiskCategory =
  | "low_risk" // Age <40, GTR, no neurologic deficit
  | "high_risk"; // Age ≥40, STR/biopsy, neurologic deficit

export type ExtentOfResection =
  | "gross_total" // GTR: >95% resection
  | "subtotal" // STR: 50–95%
  | "biopsy"; // <50% or biopsy only

export type PrimaryRecommendation =
  | "observation_after_gtr"
  | "surgery_maximal_safe_resection"
  | "rt_plus_pvc_chemotherapy"
  | "rt_plus_temozolomide"
  | "vorasidenib_idh_inhibitor"
  | "clinical_trial"
  | "multidisciplinary_evaluation"
  | "reclassify_as_gbm";

export interface LowGradeGliomaInput {
  // Molecular profile
  idhStatus: IDHStatus;
  tp53Mutation?: boolean;
  atrxLoss?: boolean;
  tertPromoterMutation?: boolean;
  egfrAmplification?: boolean;
  chromosome7Gain10Loss?: boolean; // +7/-10 pattern

  // Tumor characteristics
  tumorSizeCm: number;
  tumorCrossesMidline: boolean;
  eloquentCortexInvolvement: boolean;
  contrastEnhancement: boolean;

  // Patient factors
  ageYears: number;
  kpsScore: number; // 0–100
  neurologicDeficit: boolean;
  seizureAtPresentation: boolean;

  // Treatment history
  extentOfResection: ExtentOfResection;
  priorRadiotherapy: boolean;
  priorChemotherapy: boolean;

  // Risk stratification
  riskCategory: RiskCategory;
}

export interface LowGradeGliomaRecommendation {
  primaryRecommendation: PrimaryRecommendation;
  recommendationTitle: string;
  rationale: string;
  evidenceLevel: "IA" | "IIA" | "IIB" | "IIIA" | "IIIB" | "IVB";
  guidelineSource: string;

  // Molecular diagnosis
  molecularDiagnosis: string;
  molecularWorkup: string[];

  // Treatment details
  surgicalStrategy: string;
  adjuvantTherapy: string[];
  chemotherapyRegimen?: string;

  // Monitoring
  monitoringPlan: string[];

  // Warnings and flags
  urgentFlags: string[];
  warnings: string[];

  // Next steps
  nextSteps: string[];

  // References
  references: Array<{ citation: string; pmid?: string }>;
}

// ─── Core Logic ──────────────────────────────────────────────────────────────

export function assessLowGradeGlioma(
  input: LowGradeGliomaInput
): LowGradeGliomaRecommendation {
  const urgentFlags: string[] = [];
  const warnings: string[] = [];
  const molecularWorkup: string[] = [];
  const adjuvantTherapy: string[] = [];
  const monitoringPlan: string[] = [];

  // ── Molecular workup requirements ─────────────────────────────────────────
  molecularWorkup.push(
    "IDH1/IDH2 mutation testing: IHC (IDH1 R132H) + sequencing if IHC negative"
  );
  molecularWorkup.push("ATRX IHC: Loss suggests IDH-mutant astrocytoma");
  molecularWorkup.push(
    "1p/19q co-deletion: FISH or sequencing (oligodendroglioma diagnosis requires IDH-mutant + 1p/19q co-deleted)"
  );
  molecularWorkup.push("TERT promoter mutation sequencing");
  molecularWorkup.push("EGFR amplification (if IDH-wildtype)");
  molecularWorkup.push("+7/-10 chromosome copy number (if IDH-wildtype)");
  molecularWorkup.push("MGMT promoter methylation (guides chemotherapy response)");

  // ── IDH-wildtype → likely GBM reclassification ────────────────────────────
  if (input.idhStatus === "idh_wildtype") {
    if (
      input.tertPromoterMutation ||
      input.egfrAmplification ||
      input.chromosome7Gain10Loss
    ) {
      urgentFlags.push(
        "IDH-wildtype diffuse astrocytic tumor with TERT promoter mutation, EGFR amplification, or +7/-10: Meets criteria for IDH-wildtype Glioblastoma (WHO 2021). Reclassify and manage as GBM."
      );
      return {
        primaryRecommendation: "reclassify_as_gbm",
        recommendationTitle:
          "Reclassify as IDH-Wildtype Glioblastoma (WHO Grade 4)",
        rationale:
          "IDH-wildtype diffuse astrocytic tumor with TERT promoter mutation, EGFR amplification, or +7/-10 chromosome copy number changes meets WHO 2021 criteria for IDH-wildtype Glioblastoma regardless of histologic grade. Management should follow GBM protocols (Stupp regimen).",
        evidenceLevel: "IA",
        guidelineSource:
          "WHO Classification of Tumors of the CNS 2021 (Louis DN et al., Acta Neuropathol 2021; PMID 34185076)",
        molecularDiagnosis: "IDH-wildtype Glioblastoma (WHO Grade 4)",
        molecularWorkup,
        surgicalStrategy:
          "Maximal safe resection followed by concurrent temozolomide + RT (Stupp protocol), then adjuvant temozolomide.",
        adjuvantTherapy: [
          "Concurrent temozolomide 75 mg/m²/day during RT",
          "Adjuvant temozolomide 150–200 mg/m²/day × 5 days every 28 days × 6 cycles",
          "MGMT methylation status guides benefit from temozolomide",
          "Tumor treating fields (TTFields/Optune): Consider for newly diagnosed GBM",
        ],
        monitoringPlan: [
          "MRI brain every 8–12 weeks",
          "Pseudoprogression assessment at first post-RT MRI (6–8 weeks)",
        ],
        urgentFlags,
        warnings: [
          "This is NOT a low-grade glioma — reclassification to GBM changes prognosis and treatment significantly.",
          "Median OS for GBM: 14–16 months with Stupp regimen.",
        ],
        nextSteps: [
          "Neuro-oncology consultation for GBM management",
          "MGMT methylation testing",
          "Radiation oncology consultation for Stupp protocol",
          "Multidisciplinary neuro-oncology tumor board",
        ],
        references: getLGGReferences(),
      };
    }
  }

  // ── Molecular diagnosis label ──────────────────────────────────────────────
  let molecularDiagnosis = "Pending molecular testing";
  if (input.idhStatus === "idh_mutant_1p19q_codeleted") {
    molecularDiagnosis = "Oligodendroglioma, IDH-mutant, 1p/19q-codeleted (WHO Grade 2)";
  } else if (input.idhStatus === "idh_mutant_atrx_mutant") {
    molecularDiagnosis = "Astrocytoma, IDH-mutant (WHO Grade 2)";
  } else if (input.idhStatus === "idh_wildtype") {
    molecularDiagnosis =
      "IDH-wildtype diffuse glioma — evaluate for GBM molecular markers";
    warnings.push(
      "IDH-wildtype without GBM molecular markers: Rare. Consider repeat biopsy or expanded molecular panel."
    );
  }

  // ── Unknown molecular status ───────────────────────────────────────────────
  if (input.idhStatus === "unknown") {
    return {
      primaryRecommendation: "multidisciplinary_evaluation",
      recommendationTitle:
        "Molecular Testing Required — Defer Treatment Decision",
      rationale:
        "WHO 2021 classification requires molecular profiling (IDH, 1p/19q, ATRX, TERT) before treatment planning. Treatment decisions for diffuse gliomas must be based on integrated histomolecular diagnosis.",
      evidenceLevel: "IA",
      guidelineSource:
        "WHO Classification of Tumors of the CNS 2021 (PMID 34185076); SEOM-GEINO 2024 (PMID 38662171)",
      molecularDiagnosis: "Pending molecular testing",
      molecularWorkup,
      surgicalStrategy:
        "If not yet resected: Maximal safe resection to obtain adequate tissue for molecular profiling.",
      adjuvantTherapy: ["Defer adjuvant therapy pending molecular classification"],
      monitoringPlan: ["MRI brain with gadolinium after surgery"],
      urgentFlags,
      warnings: [
        ...warnings,
        "Do not initiate adjuvant therapy without molecular classification — treatment differs significantly between oligodendroglioma and astrocytoma.",
      ],
      nextSteps: [
        "Ensure adequate tissue for molecular testing (IDH, 1p/19q, ATRX, TERT, EGFR, MGMT)",
        "Neuro-pathology review at specialized center",
        "Neuro-oncology multidisciplinary tumor board",
        "Defer adjuvant therapy pending molecular results",
      ],
      references: getLGGReferences(),
    };
  }

  // ── Risk stratification ───────────────────────────────────────────────────
  const isHighRisk =
    input.riskCategory === "high_risk" ||
    input.ageYears >= 40 ||
    input.extentOfResection === "biopsy" ||
    input.extentOfResection === "subtotal" ||
    input.tumorSizeCm >= 6 ||
    input.tumorCrossesMidline ||
    input.neurologicDeficit;

  // ── Low-risk after GTR — observation ─────────────────────────────────────
  if (
    !isHighRisk &&
    input.extentOfResection === "gross_total" &&
    input.ageYears < 40 &&
    !input.neurologicDeficit
  ) {
    monitoringPlan.push("MRI brain every 3–6 months × 2 years, then every 6–12 months");
    monitoringPlan.push("Neurologic and neurocognitive assessment annually");

    return {
      primaryRecommendation: "observation_after_gtr",
      recommendationTitle:
        "Observation After Gross Total Resection — Low-Risk LGG",
      rationale:
        "Low-risk LGG (age <40, GTR, no neurologic deficit): Observation after GTR is acceptable. EORTC 22033-26033 showed no OS benefit of immediate RT vs observation in low-risk patients. Early adjuvant therapy reserved for high-risk features.",
      evidenceLevel: "IIA",
      guidelineSource:
        "SEOM-GEINO 2024 (PMID 38662171); EORTC 22033-26033 (Baumert BG et al., Lancet Oncol 2016)",
      molecularDiagnosis,
      molecularWorkup,
      surgicalStrategy:
        "GTR achieved. No immediate adjuvant therapy required for low-risk LGG.",
      adjuvantTherapy: [
        "Observation: Serial MRI every 3–6 months",
        "Vorasidenib (IDH inhibitor): Consider for IDH-mutant Grade 2 glioma after surgery (INDIGO trial, N Engl J Med 2023; PMID 37610921)",
        "Trigger for adjuvant therapy: Radiographic progression, new neurologic deficit, or transformation",
      ],
      monitoringPlan,
      urgentFlags,
      warnings: [
        ...warnings,
        "Vorasidenib (IDH inhibitor): INDIGO trial showed significant improvement in PFS for IDH-mutant Grade 2 glioma after surgery. Discuss with neuro-oncology.",
        input.idhStatus === "idh_mutant_atrx_mutant"
          ? "IDH-mutant astrocytoma: Higher risk of transformation to Grade 3/4 than oligodendroglioma. Closer surveillance warranted."
          : "",
      ].filter(Boolean),
      nextSteps: [
        "Neuro-oncology follow-up every 3–6 months",
        "MRI brain every 3–6 months × 2 years",
        "Discuss vorasidenib (IDH inhibitor) with neuro-oncology",
        "Seizure management if applicable (antiepileptic therapy)",
        "Neuropsychological assessment",
      ],
      references: getLGGReferences(),
    };
  }

  // ── High-risk — RT + chemotherapy ─────────────────────────────────────────
  if (isHighRisk) {
    const isOligodendroglioma =
      input.idhStatus === "idh_mutant_1p19q_codeleted";

    if (isOligodendroglioma) {
      adjuvantTherapy.push(
        "RT (54 Gy in 30 fractions) followed by PCV chemotherapy (procarbazine + CCNU + vincristine) × 6 cycles — RTOG 9802 standard (Level I-A)"
      );
      adjuvantTherapy.push(
        "Alternative: RT + temozolomide (less evidence for oligodendroglioma vs PCV)"
      );
      adjuvantTherapy.push(
        "Vorasidenib: Consider for IDH-mutant Grade 2 glioma (INDIGO trial, Level I)"
      );
    } else {
      adjuvantTherapy.push(
        "RT (54 Gy in 30 fractions) followed by PCV chemotherapy × 6 cycles — RTOG 9802 (Level I-A)"
      );
      adjuvantTherapy.push(
        "RT + temozolomide: Alternative regimen (less Level I evidence for LGG vs GBM)"
      );
      adjuvantTherapy.push(
        "Vorasidenib: Consider for IDH-mutant Grade 2 astrocytoma (INDIGO trial, Level I)"
      );
    }

    monitoringPlan.push("MRI brain every 3 months during treatment");
    monitoringPlan.push("MRI brain every 3–6 months post-treatment × 2 years");
    monitoringPlan.push("Neurocognitive assessment at baseline and annually");

    return {
      primaryRecommendation: "rt_plus_pvc_chemotherapy",
      recommendationTitle: `RT + ${isOligodendroglioma ? "PCV Chemotherapy" : "PCV or Temozolomide"} — High-Risk LGG`,
      rationale:
        "High-risk LGG (age ≥40, STR/biopsy, neurologic deficit, large tumor, or midline crossing): RT + PCV chemotherapy is the standard of care per RTOG 9802 (Level I-A). RT alone is inferior to RT + PCV for high-risk LGG. Vorasidenib (IDH inhibitor) is an emerging option per INDIGO trial.",
      evidenceLevel: "IA",
      guidelineSource:
        "SEOM-GEINO 2024 (PMID 38662171); RTOG 9802 — Buckner JC et al., N Engl J Med 2016 (PMID 26598715); INDIGO Trial — Mellinghoff IK et al., N Engl J Med 2023 (PMID 37610921)",
      molecularDiagnosis,
      molecularWorkup,
      surgicalStrategy:
        input.extentOfResection === "biopsy"
          ? "Biopsy only: Consider re-resection for maximal safe resection before adjuvant therapy if feasible."
          : "Maximal safe resection achieved. Proceed with adjuvant therapy.",
      adjuvantTherapy,
      chemotherapyRegimen: isOligodendroglioma
        ? "PCV: Procarbazine 60 mg/m²/day days 8–21, CCNU 110 mg/m²/day day 1, Vincristine 1.4 mg/m² days 8 and 29; every 8 weeks × 6 cycles"
        : "PCV (preferred per RTOG 9802) or Temozolomide 150–200 mg/m²/day × 5 days every 28 days × 12 cycles",
      monitoringPlan,
      urgentFlags,
      warnings: [
        ...warnings,
        "Radiation dose: 54 Gy in 30 fractions (standard). Higher doses not shown to improve outcomes and increase neurotoxicity.",
        input.eloquentCortexInvolvement
          ? "Eloquent cortex involvement: Awake craniotomy with cortical mapping may be required for maximal safe resection."
          : "",
        "Vorasidenib (IDH inhibitor): INDIGO trial showed 61% reduction in risk of progression or death vs placebo for IDH-mutant Grade 2 glioma after surgery. FDA approved 2024.",
      ].filter(Boolean),
      nextSteps: [
        "Radiation oncology consultation for RT planning (54 Gy/30 fractions)",
        "Neuro-oncology consultation for chemotherapy (PCV or temozolomide)",
        "Discuss vorasidenib eligibility (IDH-mutant, Grade 2, post-surgery)",
        "MGMT methylation testing",
        "Neuropsychological baseline assessment",
        "Seizure management optimization",
        input.extentOfResection === "biopsy"
          ? "Consider re-resection for maximal safe resection"
          : "",
      ].filter(Boolean),
      references: getLGGReferences(),
    };
  }

  // ── Default: surgery first ────────────────────────────────────────────────
  return {
    primaryRecommendation: "surgery_maximal_safe_resection",
    recommendationTitle: "Maximal Safe Resection — Primary Treatment",
    rationale:
      "Maximal safe resection is the primary treatment for diffuse low-grade glioma. Greater extent of resection is associated with improved OS and PFS. Eloquent cortex involvement requires awake craniotomy with cortical mapping.",
    evidenceLevel: "IVB",
    guidelineSource:
      "SEOM-GEINO 2024 (PMID 38662171); CNS 2025 LGG Guidelines",
    molecularDiagnosis,
    molecularWorkup,
    surgicalStrategy: input.eloquentCortexInvolvement
      ? "Awake craniotomy with cortical mapping and intraoperative neurophysiological monitoring for eloquent cortex involvement."
      : "Standard craniotomy for maximal safe resection. Intraoperative MRI or ultrasound to maximize EOR.",
    adjuvantTherapy: [
      "Adjuvant therapy decision based on risk stratification after surgery",
      "Low-risk (age <40, GTR): Observation acceptable",
      "High-risk (age ≥40, STR, neurologic deficit): RT + PCV chemotherapy",
    ],
    monitoringPlan: [
      "MRI brain within 48–72 hours postoperatively (extent of resection assessment)",
      "MRI brain every 3–6 months postoperatively",
    ],
    urgentFlags,
    warnings: [
      ...warnings,
      "Molecular profiling: Ensure adequate tissue for IDH, 1p/19q, ATRX, TERT, MGMT testing.",
    ],
    nextSteps: [
      "Neurosurgery consultation for resection planning",
      "Neuro-oncology multidisciplinary tumor board",
      "Functional MRI and DTI tractography for eloquent cortex mapping",
      "Ensure molecular profiling from surgical specimen",
      "Postoperative MRI within 48–72 hours",
    ],
    references: getLGGReferences(),
  };
}

// ─── Helper Functions ─────────────────────────────────────────────────────────

function getLGGReferences() {
  return [
    {
      citation:
        "Vaz-Salgado MA et al. SEOM-GEINO Clinical Guidelines for Grade 2 Gliomas (2023). Clin Transl Oncol. 2024;26(11):2856-2865.",
      pmid: "38662171",
    },
    {
      citation:
        "Louis DN et al. The 2021 WHO Classification of Tumors of the Central Nervous System. Acta Neuropathol. 2021;142(3):405-430.",
      pmid: "34185076",
    },
    {
      citation:
        "Buckner JC et al. Radiation plus Procarbazine, CCNU, and Vincristine in Low-Grade Glioma (RTOG 9802). N Engl J Med. 2016;374(14):1344-1355.",
      pmid: "27050206",
    },
    {
      citation:
        "Mellinghoff IK et al. Vorasidenib in IDH1- or IDH2-Mutant Low-Grade Glioma (INDIGO Trial). N Engl J Med. 2023;389(8):710-721.",
      pmid: "37610921",
    },
    {
      citation:
        "Baumert BG et al. Temozolomide Chemotherapy versus Radiotherapy in High-Risk Low-Grade Glioma (EORTC 22033-26033). Lancet Oncol. 2016;17(11):1521-1532.",
      pmid: "27686946",
    },
    {
      citation:
        "Shaw EG et al. Recurrence Following Neurosurgeon-Determined Gross-Total Resection of Adult Supratentorial Low-Grade Glioma. J Clin Oncol. 2012;30(31):3865-3870.",
      pmid: "23008392",
    },
    {
      citation:
        "Pignatti F et al. Prognostic Factors for Survival in Adult Patients with Cerebral Low-Grade Glioma. J Clin Oncol. 2002;20(8):2076-2084.",
      pmid: "11956268",
    },
  ];
}

export function getRecommendationColor(rec: PrimaryRecommendation): string {
  switch (rec) {
    case "reclassify_as_gbm":
      return "red";
    case "surgery_maximal_safe_resection":
      return "blue";
    case "rt_plus_pvc_chemotherapy":
    case "rt_plus_temozolomide":
      return "orange";
    case "vorasidenib_idh_inhibitor":
      return "purple";
    case "observation_after_gtr":
      return "green";
    case "clinical_trial":
      return "teal";
    case "multidisciplinary_evaluation":
      return "yellow";
    default:
      return "gray";
  }
}

export function getIDHStatusLabel(status: IDHStatus): string {
  switch (status) {
    case "idh_mutant_1p19q_codeleted":
      return "IDH-mutant, 1p/19q co-deleted (Oligodendroglioma)";
    case "idh_mutant_atrx_mutant":
      return "IDH-mutant, ATRX-loss (Astrocytoma)";
    case "idh_wildtype":
      return "IDH-wildtype (evaluate for GBM molecular markers)";
    case "unknown":
      return "Unknown — molecular testing required";
    default:
      return status;
  }
}
